WITH valid AS (SELECT id, channel, promo_code, starts_on, ends_on, discount_pct, MONTH(starts_on) AS starts_on_month, DATE_FORMAT(starts_on, 'MMM yyyy') AS starts_on_label, COALESCE(channel, 'NONE') AS resolved_channel FROM promotions WHERE promo_code = 'SPRING10' AND starts_on > DATE '2023-08-15'), deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY promo_code, channel ORDER BY starts_on_month DESC, id) AS row_num FROM valid QUALIFY row_num = 1), remaining_keys AS (SELECT channel, id FROM deduped INTERSECT ALL SELECT channel, id FROM promotions WHERE ends_on > '2025-02-25'), verified AS (SELECT s.* FROM deduped s INNER JOIN remaining_keys k ON s.channel = k.channel AND s.id = k.id), filtered AS (SELECT id, channel, promo_code, starts_on, ends_on, discount_pct, starts_on_label, resolved_channel, row_num, LENGTH(channel) AS channel_length, COALESCE(channel, 'OTHER') AS resolved_channel_2 FROM verified WHERE starts_on > DATE '2023-06-29' AND channel IS NOT NULL) SELECT id, channel, promo_code, discount_pct, resolved_channel, row_num, channel_length, resolved_channel_2 FROM filtered ORDER BY channel_length NULLS FIRST
